3	import java.util.Set;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
7	
8	/**
9	 * Shared handling for the optional owner {@code email}. Email is optional, so a
10	 * blank or missing value is left untouched; when present it must be a syntactically
11	 * valid address and is stored lower-cased.
12	 */
13	final class OwnerEmails {
14	
15	    // Syntactic check: a non-empty local part, a single '@', and a dotted domain,
16	    // none of the parts containing whitespace or a stray '@'.
17	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
18	
19	    // Disposable/throwaway email providers are rejected: a real, durable address is required.
20	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
21	            "mailinator.com", "tempmail.com", "guerrillamail.com");
22	
23	    private OwnerEmails() {
24	    }
25	
26	    /**
27	     * Normalize an optional email. Returns {@code null}/blank unchanged; otherwise
28	     * validates syntax and returns the address lower-cased.
29	     *
30	     * @throws InvalidEmailException when a value is present but not syntactically valid.
31	     */
32	    static String normalize(String email) throws InvalidEmailException {
33	        if (email == null || email.isBlank()) {
34	            return email;
35	        }
36	        String trimmed = email.trim();
37	        if (!EMAIL.matcher(trimmed).matches()) {
38	            throw new InvalidEmailException("Email must be a syntactically valid address");
39	        }
40	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
41	        String domain = normalized.substring(normalized.indexOf('@') + 1);
42	        if (DISPOSABLE_DOMAINS.contains(domain)) {
43	            throw new InvalidEmailException("Email must not use a disposable-email domain");
44	        }
45	        return normalized;
46	    }
47	}
