1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a soft-match duplicate. A new owner is a suspected duplicate of an existing owner when their
9	 * {@link OwnerIdentity#key(Owner) identityKey}s DIFFER (so it was not rejected as a hard duplicate)
10	 * yet they share the same {@link Soundex} of the last name AND the same postcode. It is created with
11	 * {@code possibleDuplicate} set true and {@code possibleDuplicateOf} set to the matching owner's id.
12	 *
13	 * <p>The soft match is intentionally broader than the identity key: two owners at the same last name
14	 * (phonetically) and postcode but with different telephones are no longer a hard household duplicate,
15	 * so this step surfaces them for review instead of rejecting them.
16	 *
17	 * <p>A declared household member (request {@code sharesHousehold} true) is NOT a suspected duplicate:
18	 * it deliberately joins an existing household, so it is created with {@code possibleDuplicate} false.
19	 *
20	 * <p>Runs before {@link SaveOwner} so the new owner has not been persisted yet and is not compared
21	 * against itself. Soft-deleted owners are ignored. The earliest matching owner (lowest id) is chosen
22	 * for stability.
23	 */
24	public class AssignPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
27	        if (Boolean.TRUE.equals(sharesHousehold)) {
28	            // Declared household member: a deliberate join, not a suspected duplicate.
29	            owner.setPossibleDuplicate(Boolean.FALSE);
30	            return;
31	        }
32	        String identityKey = OwnerIdentity.key(owner);
33	        String soundex = Soundex.of(owner.getLastName());
34	        String postcode = postcode(owner);
35	        Owner match = ownerRepository.findAll().stream()
36	                .filter(existing -> !existing.getId().equals(owner.getId()))
37	                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted())) // ignore soft-deleted owners
38	                .filter(existing -> !identityKey.equals(OwnerIdentity.key(existing)) // not a hard duplicate
39	                        && soundex.equals(Soundex.of(existing.getLastName()))
40	                        && postcode.equals(postcode(existing)))
41	                .min(java.util.Comparator.comparing(Owner::getId))
42	                .orElse(null);
43	        if (match != null) {
44	            owner.setPossibleDuplicate(Boolean.TRUE);
45	            owner.setPossibleDuplicateOf(match.getId());
46	        }
47	        else {
48	            owner.setPossibleDuplicate(Boolean.FALSE);
49	        }
50	    }
51	
52	    private static String postcode(Owner owner) {
53	        String postcode = owner.getPostcode();
54	        return postcode == null ? "" : postcode.trim();
55	    }
56	}
