7	
8	/**
9	 * Rejects creating an owner when the owner's city already contains 50 or more owners. The city is
10	 * compared case-insensitively with runs of whitespace collapsed to a single space. The owner being
11	 * created is not yet persisted, so it is not part of the count.
12	 */
13	public class EnsureCityCapacity {
14	
15	    private static final int MAX_OWNERS_PER_CITY = 50;
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws CityAtCapacityException {
19	        String city = normalize(owner.getCity());
20	        long count = ownerRepository.findAll().stream()
21	                .filter(existing -> !existing.getId().equals(owner.getId()))
22	                .filter(existing -> normalize(existing.getCity()).equals(city))
23	                .count();
24	        if (count >= MAX_OWNERS_PER_CITY) {
25	            throw new CityAtCapacityException(
26	                    "The city " + owner.getCity() + " already has " + MAX_OWNERS_PER_CITY + " or more owners");
27	        }
28	    }
29	
30	    private static String normalize(String value) {
31	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
32	    }
33	}
