8	/**
9	 * The single owner duplicate block, expressed through the {@link OwnerIdentity#key(Owner) identityKey}
10	 * (SHA-256 over normalized telephone + lower-case email + soundex of the last name). A second owner
11	 * whose whole key matches an existing one is a duplicate and is rejected (409); because the telephone
12	 * is part of the key, two owners with the same last name and postcode but different telephones have
13	 * distinct keys and are both allowed (they become a soft match — see {@link AssignPossibleDuplicate}).
14	 * The email-domain blocklist is applied earlier, in {@link BuildOwner}.
15	 *
16	 * <p>The request's {@code sharesHousehold} flag bypasses this block: a declared household member is
17	 * created even when its identity key already exists. Soft-deleted owners are ignored; existing owners
18	 * are compared by their own computed key.
19	 */
20	public class EnsureUniqueIdentity {
21	
22	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
23	            throws DuplicateIdentityException {
24	        if (Boolean.TRUE.equals(sharesHousehold)) {
25	            return; // declared household member: allowed to join an existing household
26	        }
27	        String identityKey = OwnerIdentity.key(owner);
28	        boolean inUse = ownerRepository.findAll().stream()
29	                .filter(existing -> !existing.getId().equals(owner.getId()))
30	                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted())) // ignore soft-deleted owners
31	                .anyMatch(existing -> identityKey.equals(OwnerIdentity.key(existing)));
32	        if (inUse) {
33	            throw new DuplicateIdentityException(
34	                    "An owner with identity key " + identityKey + " already exists");
35	        }
36	    }
