32	        // preferred over the flat 'address' when supplied; the composed 'address' is the normalized
33	        // 'addressLine1' with the normalized 'addressLine2' appended (single space) when present, and
34	        // falls back to the normalized flat 'address' otherwise. Composing here means the required
35	        // check below rejects an address that is blank in both forms, and every later comparison sees
36	        // the stored normalized form.
37	        request.setAddressLine1(Addresses.normalizeToNull(request.getAddressLine1()));
38	        request.setAddressLine2(Addresses.normalizeToNull(request.getAddressLine2()));
39	        request.setAddress(Addresses.compose(
40	                request.getAddressLine1(), request.getAddressLine2(), request.getAddress()));
41	        List<String> missing = new ArrayList<>();
42	        if (isBlank(request.getFirstName())) {
43	            missing.add("firstName");
44	        }
45	        if (isBlank(request.getLastName())) {
46	            missing.add("lastName");
47	        }
48	        if (isBlank(request.getAddress())) {
49	            missing.add("address");
50	        }
51	        if (isBlank(request.getCity())) {
52	            missing.add("city");
53	        }
54	        if (isBlank(request.getTelephone())) {
55	            missing.add("telephone");
56	        }
57	        if (!missing.isEmpty()) {
58	            throw new MissingOwnerFieldsException(missing);
59	        }
